local Plasma = require(game.ReplicatedStorage.Packages.Plasma)
-- 玩家选择器，调用该ui将生成一个窗口，用来选择玩家
-- 返回两个成员
-- 第一个为选中的 userId 或者 nil
-- 第二个为清除当前选中的回调函数
return Plasma.widget(function(debugger)
	local ui = debugger:getWidgets()
	local players = game.Players:GetPlayers()
	local current, setCurrent
	ui.window({
		title = `Players ({#players})`,
		closable = false,
		movable = false,
		resizable = false,
		maxSize = Vector2.new(150, 300),
	}, function()
		current, setCurrent = Plasma.useState()
		for _, player in players do
			local checbBox = ui.checkbox(player.UserId, {
				checked = current == player.UserId,
			})
			if checbBox.clicked() then
				if current == player.UserId then
					current = nil
					setCurrent(current)
				else
					current = player.UserId
					setCurrent(current)
				end
			end
			checbBox.checked = current == player.UserId
		end
	end)

	local clearSelectionHandler = function()
		setCurrent(nil)
	end
	return {
		userId = current,
		clear = clearSelectionHandler
	}
end)

